//! Checks on the vendored part of the licence list shown in "About muSQL" (#119).
//!
//! `ui/credits.json` is generated by `scripts/credits.mjs` (`just credits`) and committed.
//! The release pull request regenerates it (#149), and `just check-credits` compares it
//! with the dependencies; both are in that script, which also says what is listed.
//!
//! What stays here runs with `just test`: the vendored code under `ui/lib/` is listed by
//! hand in `scripts/vendored.json`, and this checks what can be checked about that list.

use serde::Deserialize;
use serde_json::Value;
use std::collections::BTreeSet;
use std::fs;
use std::path::{Path, PathBuf};

const OUT: &str = "ui/credits.json";

/// Where vendored code lives. Every directory in it must have an entry in the list.
const VENDOR_DIR: &str = "ui/lib";

/// The hand-written list of vendored code, read by `scripts/credits.mjs` too.
const VENDORED_LIST: &str = "scripts/vendored.json";

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("src-tauri has a parent")
        .to_path_buf()
}

/// One entry of `scripts/vendored.json` (its `url` is not checked here).
#[derive(Deserialize)]
struct Vendored {
    name: String,
    version: String,
    license: String,
    file: String,
}

/// `name version | licence`: how an entry is compared with `ui/credits.json`.
fn key(name: &str, version: &str, license: &str) -> String {
    format!("{name} {version} | {license}")
}

#[test]
fn vendored_list_covers_what_is_vendored() {
    let body = fs::read_to_string(root().join(VENDORED_LIST))
        .unwrap_or_else(|e| panic!("cannot read {VENDORED_LIST}: {e}"));
    let list: Vec<Vendored> =
        serde_json::from_str(&body).unwrap_or_else(|e| panic!("{VENDORED_LIST}: {e}"));

    // Every licence file exists.
    for v in &list {
        assert!(
            root().join(&v.file).is_file(),
            "{}: licence file {} is missing",
            v.name,
            v.file
        );
    }

    // Every directory under ui/lib has an entry (its licence file sits in it).
    let covered: BTreeSet<PathBuf> = list
        .iter()
        .filter_map(|v| Path::new(&v.file).parent().map(Path::to_path_buf))
        .collect();
    for entry in fs::read_dir(root().join(VENDOR_DIR)).expect("ui/lib is listable") {
        let path = entry.expect("dir entry").path();
        if !path.is_dir() {
            continue;
        }
        let rel = Path::new(VENDOR_DIR).join(path.file_name().expect("a name"));
        assert!(
            covered.contains(&rel),
            "{} is vendored but has no entry in {VENDORED_LIST}",
            rel.display()
        );
    }

    // CodeMirror's vendored files say which version they are.
    let version = &list
        .iter()
        .find(|v| v.name == "CodeMirror")
        .expect("CodeMirror is vendored")
        .version;
    let header = fs::read_to_string(root().join("ui/lib/codemirror/codemirror.min.js"))
        .expect("codemirror.min.js is readable");
    let header: String = header.chars().take(400).collect();
    assert!(
        header.contains(&format!("codemirror@{version}/")),
        "{VENDORED_LIST} says CodeMirror {version}, but ui/lib/codemirror/codemirror.min.js is \
         another version. Update {VENDORED_LIST} and the LICENSE file, then run `just credits`."
    );

    // The committed list carries the vendored entries as they are listed. (dependabot never
    // touches ui/lib/, so a mismatch means the list was edited and not regenerated.)
    let body = fs::read_to_string(root().join(OUT)).expect("credits.json is readable");
    let credits: Value = serde_json::from_str(&body).expect("credits.json is JSON");
    let field = |p: &Value, k: &str| p[k].as_str().unwrap_or_default().to_owned();
    let listed: BTreeSet<String> = credits["packages"]
        .as_array()
        .expect("packages is a list")
        .iter()
        .filter(|p| p["vendored"].as_bool().unwrap_or(false))
        .map(|p| {
            key(
                &field(p, "name"),
                &field(p, "version"),
                &field(p, "license"),
            )
        })
        .collect();
    let expected: BTreeSet<String> = list
        .iter()
        .map(|v| key(&v.name, &v.version, &v.license))
        .collect();
    assert_eq!(
        listed, expected,
        "{OUT} does not list what {VENDORED_LIST} lists. Run `just credits`."
    );
}
